*** Begin Patch
*** Add File: /workspace/submission/infra/main.tf
+terraform {
+  required_version = ">= 1.9.0"
+  required_providers {
+    aws = { source = "hashicorp/aws", version = "6.51.0" }
+  }
+  backend "local" { path = "terraform.tfstate" }
+}
+
+variable "config_path" {
+  type    = string
+  default = "/workspace/config/config.json"
+}
+locals {
+  c = jsondecode(file(var.config_path))
+  p = local.c.resource_prefix
+  endpoint = local.c.aws_endpoint_url
+  roles = toset(["ecs_execution", "ecs_task", "projector", "relay", "archiver", "scheduler"])
+  workloads = { api = "api", projector = "projector", relay = "outbox-relay", archiver = "audit-archiver" }
+  key_usages = toset(["database", "messaging", "projection", "audit"])
+  azs = ["${local.c.region}a", "${local.c.region}b"]
+}
+provider "aws" {
+  region = local.c.region
+  access_key = "test"
+  secret_key = "test"
+  skip_credentials_validation = true
+  skip_metadata_api_check = true
+  skip_requesting_account_id = true
+  skip_region_validation = true
+  s3_use_path_style = true
+  endpoints {
+    ec2 = local.endpoint
+    elbv2 = local.endpoint
+    ecs = local.endpoint
+    rds = local.endpoint
+    sqs = local.endpoint
+    lambda = local.endpoint
+    dynamodb = local.endpoint
+    elasticache = local.endpoint
+    s3 = local.endpoint
+    scheduler = local.endpoint
+    cognitoidp = local.endpoint
+    iam = local.endpoint
+    kms = local.endpoint
+    cloudwatchlogs = local.endpoint
+    sts = local.endpoint
+    tagging = local.endpoint
+  }
+  default_tags { tags = { ClearLedgerDeployment = local.p } }
+}
+data "aws_caller_identity" "current" {}
+locals {
+  account = data.aws_caller_identity.current.account_id
+  arn_base = "arn:aws"
+  function_arns = { for w in ["projector", "relay", "archiver"] : w => "arn:aws:lambda:${local.c.region}:${local.account}:function:${local.p}-${local.workloads[w]}" }
+}
+
+resource "aws_vpc" "main" {
+  cidr_block = "10.42.0.0/16"
+  enable_dns_support = true
+  enable_dns_hostnames = true
+  tags = { Name = "${local.p}-vpc" }
+}
+resource "aws_subnet" "public" {
+  count = 2
+  vpc_id = aws_vpc.main.id
+  cidr_block = "10.42.${count.index}.0/24"
+  availability_zone = local.azs[count.index]
+  map_public_ip_on_launch = true
+  tags = { Name = "${local.p}-public-${count.index}" }
+}
+resource "aws_subnet" "private" {
+  count = 2
+  vpc_id = aws_vpc.main.id
+  cidr_block = "10.42.${count.index + 10}.0/24"
+  availability_zone = local.azs[count.index]
+  map_public_ip_on_launch = false
+  tags = { Name = "${local.p}-private-${count.index}" }
+}
+resource "aws_internet_gateway" "main" {
+  vpc_id = aws_vpc.main.id
+  tags = { Name = "${local.p}-igw" }
+}
+resource "aws_route_table" "public" {
+  vpc_id = aws_vpc.main.id
+  route {
+    cidr_block = "0.0.0.0/0"
+    gateway_id = aws_internet_gateway.main.id
+  }
+  tags = { Name = "${local.p}-public" }
+}
+resource "aws_route_table" "private" {
+  vpc_id = aws_vpc.main.id
+  route = []
+  tags = { Name = "${local.p}-private" }
+}
+resource "aws_route_table_association" "public" {
+  count = 2
+  subnet_id = aws_subnet.public[count.index].id
+  route_table_id = aws_route_table.public.id
+}
+resource "aws_route_table_association" "private" {
+  count = 2
+  subnet_id = aws_subnet.private[count.index].id
+  route_table_id = aws_route_table.private.id
+}
+resource "aws_security_group" "alb" {
+  name = "${local.p}-alb"
+  vpc_id = aws_vpc.main.id
+  ingress {
+    from_port = 80
+    to_port = 80
+    protocol = "tcp"
+    cidr_blocks = ["0.0.0.0/0"]
+  }
+  egress {
+    from_port = 8080
+    to_port = 8080
+    protocol = "tcp"
+    cidr_blocks = [aws_vpc.main.cidr_block]
+  }
+}
+resource "aws_security_group" "ecs" {
+  name = "${local.p}-ecs"
+  vpc_id = aws_vpc.main.id
+  ingress {
+    from_port = 8080
+    to_port = 8080
+    protocol = "tcp"
+    security_groups = [aws_security_group.alb.id]
+  }
+  egress {
+    from_port = 0
+    to_port = 0
+    protocol = "-1"
+    cidr_blocks = ["0.0.0.0/0"]
+  }
+}
+resource "aws_security_group" "rds" {
+  name = "${local.p}-rds"
+  vpc_id = aws_vpc.main.id
+  ingress {
+    from_port = 5432
+    to_port = 5432
+    protocol = "tcp"
+    cidr_blocks = [aws_vpc.main.cidr_block]
+  }
+  egress = []
+}
+resource "aws_security_group" "valkey" {
+  name = "${local.p}-valkey"
+  vpc_id = aws_vpc.main.id
+  ingress {
+    from_port = 6379
+    to_port = 6379
+    protocol = "tcp"
+    cidr_blocks = [aws_vpc.main.cidr_block]
+  }
+  egress = []
+}
+
+resource "aws_kms_key" "store" {
+  for_each = local.key_usages
+  description = "${local.p}-${each.key}"
+  enable_key_rotation = true
+  deletion_window_in_days = 10
+  tags = { Name = "${local.p}-${each.key}", ClearLedgerKeyUsage = each.key }
+}
+resource "aws_kms_alias" "store" {
+  for_each = local.key_usages
+  name = "alias/${local.p}-${each.key}"
+  target_key_id = aws_kms_key.store[each.key].key_id
+}
+resource "aws_cloudwatch_log_group" "workload" {
+  for_each = local.workloads
+  name = "/clearledger/${local.p}/${each.value}"
+  retention_in_days = 14
+}
+resource "aws_db_subnet_group" "main" {
+  name = "${local.p}-database"
+  subnet_ids = aws_subnet.private[*].id
+}
+resource "aws_db_instance" "main" {
+  identifier = "${local.p}-database"
+  engine = "postgres"
+  engine_version = "16.3"
+  instance_class = "db.t4g.micro"
+  allocated_storage = 20
+  db_name = local.c.db_name
+  username = local.c.db_username
+  password = local.c.db_password
+  storage_encrypted = true
+  kms_key_id = aws_kms_key.store["database"].arn
+  publicly_accessible = false
+  skip_final_snapshot = true
+  db_subnet_group_name = aws_db_subnet_group.main.name
+  vpc_security_group_ids = [aws_security_group.rds.id]
+  apply_immediately = true
+  backup_retention_period = 7
+}
+resource "aws_sqs_queue" "dlq" {
+  name = "${local.p}-events-dlq"
+  kms_master_key_id = aws_kms_key.store["messaging"].arn
+  message_retention_seconds = 1209600
+}
+resource "aws_sqs_queue" "main" {
+  name = "${local.p}-events"
+  kms_master_key_id = aws_kms_key.store["messaging"].arn
+  visibility_timeout_seconds = 3
+  receive_wait_time_seconds = 2
+  message_retention_seconds = 172800
+  redrive_policy = jsonencode({ deadLetterTargetArn = aws_sqs_queue.dlq.arn, maxReceiveCount = 4 })
+}
+resource "aws_dynamodb_table" "main" {
+  name = "${local.p}-projections"
+  billing_mode = "PAY_PER_REQUEST"
+  hash_key = "PK"
+  range_key = "SK"
+  dynamic "attribute" {
+    for_each = toset(["PK", "SK", "GSI1PK", "GSI1SK"])
+    content {
+      name = attribute.value
+      type = "S"
+    }
+  }
+  global_secondary_index {
+    name = "AccountIndex"
+    hash_key = "GSI1PK"
+    range_key = "GSI1SK"
+    projection_type = "ALL"
+  }
+  point_in_time_recovery { enabled = true }
+  server_side_encryption {
+    enabled = true
+    kms_key_arn = aws_kms_key.store["projection"].arn
+  }
+}
+resource "aws_elasticache_subnet_group" "main" {
+  name = "${local.p}-valkey"
+  subnet_ids = aws_subnet.private[*].id
+}
+resource "aws_elasticache_replication_group" "main" {
+  replication_group_id = "${local.p}-valkey"
+  description = "${local.p} projection cache"
+  engine = "valkey"
+  engine_version = "8.0"
+  node_type = "cache.t4g.micro"
+  num_cache_clusters = 1
+  port = 6379
+  subnet_group_name = aws_elasticache_subnet_group.main.name
+  security_group_ids = [aws_security_group.valkey.id]
+  apply_immediately = true
+}
+resource "aws_s3_bucket" "audit" {
+  bucket = "${local.p}-audit"
+  force_destroy = true
+}
+resource "aws_s3_bucket_versioning" "audit" {
+  bucket = aws_s3_bucket.audit.id
+  versioning_configuration { status = "Enabled" }
+}
+resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
+  bucket = aws_s3_bucket.audit.id
+  rule {
+    apply_server_side_encryption_by_default {
+      sse_algorithm = "aws:kms"
+      kms_master_key_id = aws_kms_key.store["audit"].arn
+    }
+  }
+}
+resource "aws_s3_bucket_public_access_block" "audit" {
+  bucket = aws_s3_bucket.audit.id
+  block_public_acls = true
+  block_public_policy = true
+  ignore_public_acls = true
+  restrict_public_buckets = true
+}
+resource "aws_cognito_user_pool" "main" { name = "${local.p}-auth" }
+resource "aws_cognito_resource_server" "main" {
+  user_pool_id = aws_cognito_user_pool.main.id
+  identifier = "clearledger"
+  name = "${local.p}-scopes"
+  dynamic "scope" {
+    for_each = toset(["read", "write", "admin"])
+    content {
+      scope_name = scope.value
+      scope_description = "ClearLedger ${scope.value}"
+    }
+  }
+}
+resource "aws_cognito_user_pool_client" "scope" {
+  for_each = toset(["read", "write", "admin"])
+  name = "${local.p}-${each.key}"
+  user_pool_id = aws_cognito_user_pool.main.id
+  generate_secret = true
+  allowed_oauth_flows_user_pool_client = true
+  allowed_oauth_flows = ["client_credentials"]
+  allowed_oauth_scopes = ["${aws_cognito_resource_server.main.identifier}/${each.key}"]
+}
+
+locals {
+  database_url = "postgres://${urlencode(local.c.db_username)}:${urlencode(local.c.db_password)}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${local.c.db_name}"
+  valkey_url = "redis://${aws_elasticache_replication_group.main.primary_endpoint_address}:${aws_elasticache_replication_group.main.port}"
+  issuer = "${local.endpoint}/${aws_cognito_user_pool.main.id}"
+  common_env = {
+    AWS_REGION = local.c.region
+    AWS_DEFAULT_REGION = local.c.region
+    AWS_ACCESS_KEY_ID = "test"
+    AWS_SECRET_ACCESS_KEY = "test"
+    AWS_ENDPOINT_URL = local.endpoint
+  }
+  worker_env = {
+    projector = { PROJECTION_TABLE = aws_dynamodb_table.main.name, VALKEY_URL = local.valkey_url }
+    relay = { DATABASE_URL = local.database_url, SQS_QUEUE_URL = aws_sqs_queue.main.url, OUTBOX_BATCH_SIZE = "50" }
+    archiver = { DATABASE_URL = local.database_url, AUDIT_BUCKET = aws_s3_bucket.audit.bucket, AUDIT_PREFIX = "ledger-audit/" }
+  }
+}
+resource "aws_lambda_function" "worker" {
+  for_each = toset(["projector", "relay", "archiver"])
+  function_name = "${local.p}-${local.workloads[each.key]}"
+  package_type = "Image"
+  image_uri = local.c["${each.key}_image"]
+  role = aws_iam_role.workload[each.key].arn
+  timeout = 3
+  memory_size = 256
+  environment {
+    variables = merge(local.common_env, local.worker_env[each.key], { CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.workload[each.key].name })
+  }
+  depends_on = [aws_iam_role_policy.workload]
+}
+resource "aws_lambda_event_source_mapping" "projector" {
+  event_source_arn = aws_sqs_queue.main.arn
+  function_name = aws_lambda_function.worker["projector"].arn
+  enabled = true
+  batch_size = 5
+  maximum_batching_window_in_seconds = 0
+  function_response_types = ["ReportBatchItemFailures"]
+}
+resource "aws_scheduler_schedule" "worker" {
+  for_each = { relay = "rate(1 minute)", archiver = "rate(5 minutes)" }
+  name = "${local.p}-${each.key}"
+  state = "ENABLED"
+  schedule_expression = each.value
+  flexible_time_window { mode = "OFF" }
+  target {
+    arn = aws_lambda_function.worker[each.key].arn
+    role_arn = aws_iam_role.workload["scheduler"].arn
+    input = "{}"
+  }
+}
+resource "aws_lb" "main" {
+  name = "${local.p}-api"
+  internal = false
+  load_balancer_type = "application"
+  subnets = aws_subnet.public[*].id
+  security_groups = [aws_security_group.alb.id]
+}
+resource "aws_lb_target_group" "main" {
+  name = "${local.p}-api"
+  port = 8080
+  protocol = "HTTP"
+  target_type = "ip"
+  vpc_id = aws_vpc.main.id
+  health_check {
+    path = "/health/ready"
+    protocol = "HTTP"
+    matcher = "200"
+  }
+}
+resource "aws_lb_listener" "main" {
+  load_balancer_arn = aws_lb.main.arn
+  port = 80
+  protocol = "HTTP"
+  default_action {
+    type = "forward"
+    target_group_arn = aws_lb_target_group.main.arn
+  }
+}
+resource "aws_ecs_cluster" "main" {
+  name = "${local.p}-cluster"
+  setting {
+    name = "containerInsights"
+    value = "enabled"
+  }
+}
+resource "aws_ecs_task_definition" "api" {
+  family = "${local.p}-api"
+  requires_compatibilities = ["FARGATE"]
+  network_mode = "awsvpc"
+  cpu = "256"
+  memory = "512"
+  execution_role_arn = aws_iam_role.workload["ecs_execution"].arn
+  task_role_arn = aws_iam_role.workload["ecs_task"].arn
+  container_definitions = jsonencode([{
+    name = "api", image = local.c.api_image, essential = true
+    portMappings = [{ containerPort = 8080, hostPort = 8080, protocol = "tcp" }]
+    environment = [for k, v in merge(local.common_env, {
+      PORT = "8080", DATABASE_URL = local.database_url, SQS_QUEUE_URL = aws_sqs_queue.main.url
+      PROJECTION_TABLE = aws_dynamodb_table.main.name, VALKEY_URL = local.valkey_url, CACHE_TTL_SECONDS = "90"
+      AUTH_ISSUER = local.issuer, AUTH_JWKS_URL = "${local.issuer}/.well-known/jwks.json"
+      AUTH_AUDIENCES = join(",", [for s in ["read", "write", "admin"] : aws_cognito_user_pool_client.scope[s].id])
+      CLOUDWATCH_LOG_GROUP = aws_cloudwatch_log_group.workload["api"].name
+    }) : { name = k, value = v }]
+    logConfiguration = { logDriver = "awslogs", options = {
+      awslogs-group = aws_cloudwatch_log_group.workload["api"].name
+      awslogs-region = local.c.region
+      awslogs-stream-prefix = "api"
+    } }
+  }])
+}
+resource "aws_ecs_service" "api" {
+  name = "${local.p}-api"
+  cluster = aws_ecs_cluster.main.id
+  task_definition = aws_ecs_task_definition.api.arn
+  launch_type = "FARGATE"
+  desired_count = 2
+  network_configuration {
+    subnets = aws_subnet.private[*].id
+    security_groups = [aws_security_group.ecs.id]
+    assign_public_ip = false
+  }
+  load_balancer {
+    target_group_arn = aws_lb_target_group.main.arn
+    container_name = "api"
+    container_port = 8080
+  }
+  depends_on = [aws_lb_listener.main, aws_iam_role_policy.workload]
+}
*** Add File: /workspace/submission/infra/iam.tf
+resource "aws_iam_role" "workload" {
+  for_each = local.roles
+  name = "${local.p}-${each.key}"
+  assume_role_policy = jsonencode({ Version = "2012-10-17", Statement = [{
+    Effect = "Allow", Action = "sts:AssumeRole", Principal = { Service = (
+      startswith(each.key, "ecs_") ? "ecs-tasks.amazonaws.com" : each.key == "scheduler" ? "scheduler.amazonaws.com" : "lambda.amazonaws.com"
+    ) }
+  }] })
+  tags = { ClearLedgerRole = each.key }
+}
+locals {
+  keys = [for k in aws_kms_key.store : k.arn]
+  queues = [aws_sqs_queue.main.arn, aws_sqs_queue.dlq.arn]
+  dynamo = [aws_dynamodb_table.main.arn, "${aws_dynamodb_table.main.arn}/index/AccountIndex"]
+  s3_resources = [aws_s3_bucket.audit.arn, "${aws_s3_bucket.audit.arn}/*"]
+  sqs_forbidden = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
+  dynamo_forbidden = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
+  s3_forbidden = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
+  log_actions = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
+  kms_actions = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
+  role_log = { ecs_execution = "api", ecs_task = "api", projector = "projector", relay = "relay", archiver = "archiver", scheduler = "" }
+  role_keys = {
+    ecs_execution = [], scheduler = [], ecs_task = ["messaging", "projection"]
+    projector = ["messaging", "projection"], relay = ["messaging", "database"], archiver = ["audit", "database"]
+  }
+  specific_allow = {
+    ecs_execution = []
+    ecs_task = [
+      { Effect = "Allow", Action = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Allow", Action = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"], Resource = local.dynamo }
+    ]
+    projector = [
+      { Effect = "Allow", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage", "sqs:GetQueueAttributes", "sqs:ChangeMessageVisibility"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Allow", Action = ["sqs:SendMessage"], Resource = [aws_sqs_queue.dlq.arn] },
+      { Effect = "Allow", Action = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:Query"], Resource = local.dynamo }
+    ]
+    relay = [{ Effect = "Allow", Action = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"], Resource = [aws_sqs_queue.main.arn] }]
+    archiver = [
+      { Effect = "Allow", Action = ["s3:PutObject", "s3:GetObject", "s3:AbortMultipartUpload"], Resource = ["${aws_s3_bucket.audit.arn}/ledger-audit/*"] },
+      { Effect = "Allow", Action = ["s3:ListBucket", "s3:GetBucketLocation"], Resource = [aws_s3_bucket.audit.arn] }
+    ]
+    scheduler = [{ Effect = "Allow", Action = ["lambda:InvokeFunction"], Resource = [local.function_arns.relay, local.function_arns.archiver] }]
+  }
+  specific_deny = {
+    ecs_execution = [
+      { Effect = "Deny", Action = local.sqs_forbidden, Resource = local.queues },
+      { Effect = "Deny", Action = local.dynamo_forbidden, Resource = local.dynamo },
+      { Effect = "Deny", Action = local.s3_forbidden, Resource = local.s3_resources }
+    ]
+    ecs_task = [
+      { Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Deny", Action = local.sqs_forbidden, Resource = [aws_sqs_queue.dlq.arn] },
+      { Effect = "Deny", Action = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"], Resource = [aws_dynamodb_table.main.arn] },
+      { Effect = "Deny", Action = local.s3_forbidden, Resource = local.s3_resources }
+    ]
+    projector = [
+      { Effect = "Deny", Action = ["sqs:SendMessage"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [aws_sqs_queue.dlq.arn] },
+      { Effect = "Deny", Action = ["dynamodb:DeleteItem", "dynamodb:DeleteTable"], Resource = [aws_dynamodb_table.main.arn] },
+      { Effect = "Deny", Action = local.s3_forbidden, Resource = local.s3_resources }
+    ]
+    relay = [
+      { Effect = "Deny", Action = ["sqs:ReceiveMessage", "sqs:DeleteMessage"], Resource = [aws_sqs_queue.main.arn] },
+      { Effect = "Deny", Action = local.sqs_forbidden, Resource = [aws_sqs_queue.dlq.arn] },
+      { Effect = "Deny", Action = local.dynamo_forbidden, Resource = local.dynamo },
+      { Effect = "Deny", Action = local.s3_forbidden, Resource = local.s3_resources }
+    ]
+    archiver = [
+      { Effect = "Deny", Action = ["s3:DeleteObject", "s3:DeleteObjectVersion"], Resource = local.s3_resources },
+      { Effect = "Deny", Action = local.sqs_forbidden, Resource = local.queues },
+      { Effect = "Deny", Action = local.dynamo_forbidden, Resource = local.dynamo }
