+ OR p->>'eventId' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN RETURN false; END IF;
+ v := (p->>'version')::integer; sid := (p->>'settlementId')::uuid; eid := (p->>'eventId')::uuid;
